import "C"

const (
	defaultCapacity = 4096
	maxPDFSize     = 10 * 1024 * 1024
)

type EncryptedStore struct {
	mu       sync.RWMutex
	basePath string
	key      []byte
}

type PDFGenerator struct {
	store    *EncryptedStore
	contexts map[string]*renderHandle
	mu       sync.Mutex
}

type renderHandle struct {
	ctx      *C.RenderContext
	finished bool
}

func NewEncryptedStore(basePath string, hexKey string) (*EncryptedStore, error) {
	key, err := hex.DecodeString(hexKey)
	if err != nil {
		return nil, fmt.Errorf("invalid key: %w", err)
	}
	if len(key) != 32 {
		return nil, fmt.Errorf("key must be 256 bits")
	}
	cleanPath := filepath.Clean(basePath)
	if err := os.MkdirAll(cleanPath, 0700); err != nil {
		return nil, err
	}
	return &EncryptedStore{basePath: cleanPath, key: key}, nil
}

func (s *EncryptedStore) encrypt(plaintext []byte) ([]byte, error) {
	block, err := aes.NewCipher(s.key)
	if err != nil {
		return nil, err
	}
	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return nil, err
	}
	nonce := make([]byte, gcm.NonceSize())
	if _, err := io.ReadFull(rand.Reader, nonce); err != nil {
		return nil, err
	}
	return gcm.Seal(nonce, nonce, plaintext, nil), nil
}

func (s *EncryptedStore) Save(id string, data []byte) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	encrypted, err := s.encrypt(data)
	if err != nil {
		return err
	}
	safeName := filepath.Base(id)
	path := filepath.Join(s.basePath, safeName+".enc")
	return os.WriteFile(path, encrypted, 0600)
}

func NewPDFGenerator(store *EncryptedStore) *PDFGenerator {
	return &PDFGenerator{
		store:    store,
		contexts: make(map[string]*renderHandle),
	}
}

func (g *PDFGenerator) BeginRender(docID string, estimatedSize int) error {
	g.mu.Lock()
	defer g.mu.Unlock()
	if _, exists := g.contexts[docID]; exists {
		return fmt.Errorf("render already in progress for %s", docID)
	}
	cap := estimatedSize
	if cap <= 0 || cap > maxPDFSize {
		cap = defaultCapacity
	}
	ctx := C.create_context(C.int(cap))
	if ctx == nil {
		return fmt.Errorf("failed to create render context")
	}
	g.contexts[docID] = &renderHandle{ctx: ctx, finished: false}
	return nil
}

func (g *PDFGenerator) AddPage(docID string, pageData []byte) error {
	g.mu.Lock()
	handle, exists := g.contexts[docID]
	if !exists {
		g.mu.Unlock()
		return fmt.Errorf("no render context for %s", docID)
	}
	if handle.finished {
		g.mu.Unlock()
		return fmt.Errorf("render already finished for %s", docID)
	}
	if len(pageData) == 0 {
		g.mu.Unlock()
		return nil
	}
	cData := C.CBytes(pageData)
	C.render_page(handle.ctx, (*C.uchar)(cData), C.int(len(pageData)))
	C.free(cData)
	g.mu.Unlock()
	return nil
}

func (g *PDFGenerator) FinishRender(docID string) error {
	g.mu.Lock()
	handle, exists := g.contexts[docID]
	if !exists {
		g.mu.Unlock()
		return fmt.Errorf("no render context for %s", docID)
	}
	handle.finished = true
	delete(g.contexts, docID)

	var outLen C.int
	renderedPtr := C.get_rendered(handle.ctx, &outLen)
	result := C.GoBytes(unsafe.Pointer(renderedPtr), outLen)

	C.destroy_context(handle.ctx)
	g.mu.Unlock()

	if err := g.store.Save(docID, result); err != nil {
		return fmt.Errorf("failed to save: %w", err)
	}

	return nil
}

func (g *PDFGenerator) CancelRender(docID string) {
	g.mu.Lock()
	defer g.mu.Unlock()
	if handle, exists := g.contexts[docID]; exists {
		C.destroy_context(handle.ctx)
		delete(g.contexts, docID)
	}
}
